Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$PagePath = Join-Path $Root "app\page.tsx"
$ComponentPath = Join-Path $Root "components\home\HomeAiChat.tsx"
$RoutePath = Join-Path $Root "app\api\public\home-chat\route.ts"

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $Root ".orcaly-backups\home-ai-chat-v2-$Timestamp"
$PageBackup = Join-Path $BackupRoot "app-page.tsx"
$ComponentBackup = Join-Path $BackupRoot "HomeAiChat.tsx"
$RouteBackup = Join-Path $BackupRoot "home-chat-route.ts"

$HadComponent = Test-Path -LiteralPath $ComponentPath
$HadRoute = Test-Path -LiteralPath $RoutePath

$ComponentBase64 = @'

'@

$RouteWithRateLimitBase64 = @'

'@

$RouteWithoutRateLimitBase64 = @'

'@

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
}

function Write-Utf8File(
    [string]$Path,
    [string]$Base64
) {
    $Parent = Split-Path -Parent $Path

    if ($Parent) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    $CleanBase64 = $Base64 -replace "\s", ""
    $Bytes = [Convert]::FromBase64String($CleanBase64)
    [System.IO.File]::WriteAllBytes($Path, $Bytes)
}

function Restore-ChatFiles {
    Write-Host "[AVISO] Restaurando arquivos anteriores..." -ForegroundColor Yellow

    if (Test-Path -LiteralPath $PageBackup) {
        Copy-Item -LiteralPath $PageBackup -Destination $PagePath -Force
    }

    if (Test-Path -LiteralPath $ComponentBackup) {
        New-Item `
            -ItemType Directory `
            -Path (Split-Path -Parent $ComponentPath) `
            -Force | Out-Null

        Copy-Item `
            -LiteralPath $ComponentBackup `
            -Destination $ComponentPath `
            -Force
    }
    elseif (-not $HadComponent -and (Test-Path -LiteralPath $ComponentPath)) {
        Remove-Item -LiteralPath $ComponentPath -Force
    }

    if (Test-Path -LiteralPath $RouteBackup) {
        New-Item `
            -ItemType Directory `
            -Path (Split-Path -Parent $RoutePath) `
            -Force | Out-Null

        Copy-Item `
            -LiteralPath $RouteBackup `
            -Destination $RoutePath `
            -Force
    }
    elseif (-not $HadRoute -and (Test-Path -LiteralPath $RoutePath)) {
        Remove-Item -LiteralPath $RoutePath -Force
    }
}

Write-Section "ORCALY - ASSISTENTE COMERCIAL COM IA V2"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

if (-not (Test-Path -LiteralPath $PagePath)) {
    throw "Arquivo app/page.tsx não encontrado."
}

New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null
Copy-Item -LiteralPath $PagePath -Destination $PageBackup -Force

if ($HadComponent) {
    Copy-Item `
        -LiteralPath $ComponentPath `
        -Destination $ComponentBackup `
        -Force
}

if ($HadRoute) {
    Copy-Item `
        -LiteralPath $RoutePath `
        -Destination $RouteBackup `
        -Force
}

Write-Host "[OK] Backup: $BackupRoot" -ForegroundColor Green

try {
    Write-Section "ATUALIZANDO WIDGET E API"

    Write-Utf8File $ComponentPath $ComponentBase64

    $RateLimitPath = Join-Path $Root "lib\security\rate-limit.ts"

    if (Test-Path -LiteralPath $RateLimitPath) {
        Write-Utf8File $RoutePath $RouteWithRateLimitBase64
        Write-Host "[OK] API com rate limit persistente." -ForegroundColor Green
    }
    else {
        Write-Utf8File $RoutePath $RouteWithoutRateLimitBase64
        Write-Host "[AVISO] Rate limit persistente não encontrado; API criada sem esse import." -ForegroundColor Yellow
    }

    $PageContent = [System.IO.File]::ReadAllText(
        $PagePath,
        [System.Text.Encoding]::UTF8
    )

    $ImportLine = "import HomeAiChat from '@/components/home/HomeAiChat'"

    if (-not $PageContent.Contains($ImportLine)) {
        $FirstLineEnd = $PageContent.IndexOf("`n")

        if ($FirstLineEnd -lt 0) {
            throw "Não foi possível inserir o import do chat."
        }

        $PageContent = $PageContent.Insert(
            $FirstLineEnd + 1,
            "$ImportLine`r`n"
        )
    }

    if (-not $PageContent.Contains("<HomeAiChat />")) {
        $MainCloseIndex = $PageContent.LastIndexOf("</main>")

        if ($MainCloseIndex -lt 0) {
            throw "Não foi possível localizar o fechamento da Home."
        }

        $PageContent = $PageContent.Insert(
            $MainCloseIndex,
            "      <HomeAiChat />`r`n"
        )
    }

    [System.IO.File]::WriteAllText(
        $PagePath,
        $PageContent,
        [System.Text.UTF8Encoding]::new($false)
    )

    Write-Host "[OK] Widget atualizado." -ForegroundColor Green
    Write-Host "[OK] API atualizada." -ForegroundColor Green
    Write-Host "[OK] Home integrada." -ForegroundColor Green

    Write-Section "VALIDANDO IMPLEMENTAÇÃO"

    $ComponentContent = [System.IO.File]::ReadAllText(
        $ComponentPath,
        [System.Text.Encoding]::UTF8
    )

    $RouteContent = [System.IO.File]::ReadAllText(
        $RoutePath,
        [System.Text.Encoding]::UTF8
    )

    $ComponentChecks = @(
        "ORCALY_HOME_AI_CHAT_V2",
        "Descobrir meu plano ideal",
        "localStorage",
        "clearConversation",
        "message.action",
        "orcalybr@gmail.com"
    )

    foreach ($Check in $ComponentChecks) {
        if (-not $ComponentContent.Contains($Check)) {
            throw "Validação do componente falhou: $Check"
        }

        Write-Host "[OK] $Check" -ForegroundColor Green
    }

    $RouteChecks = @(
        "ORCALY_HOME_AI_CHAT_API_V2",
        "AI_GATEWAY_API_KEY",
        "openai/gpt-5.6-luna",
        "openai/gpt-5.4",
        "response_format",
        "json_schema",
        "guidedAnswer",
        "ALLOWED_ACTIONS"
    )

    foreach ($Check in $RouteChecks) {
        if (-not $RouteContent.Contains($Check)) {
            throw "Validação da API falhou: $Check"
        }

        Write-Host "[OK] $Check" -ForegroundColor Green
    }

    git --no-pager diff --check -- `
        "app/page.tsx" `
        "components/home/HomeAiChat.tsx" `
        "app/api/public/home-chat/route.ts"

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content `
        -LiteralPath (Join-Path $Root "package.json") `
        -Raw |
        ConvertFrom-Json

    if ($Package.scripts.PSObject.Properties.Name -contains "security:check") {
        Write-Section "VALIDANDO SEGURANÇA"

        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Host "[OK] SECURITY_CHECK_EXIT_CODE=0" -ForegroundColor Green
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Write-Section "ASSISTENTE COMERCIAL APRIMORADO"

    Write-Host "Modelo principal: openai/gpt-5.6-luna"
    Write-Host "Modelo reserva: openai/gpt-5.4"
    Write-Host "Resposta estruturada: ativa"
    Write-Host "Recomendação de plano: ativa"
    Write-Host "Botões contextuais: ativos"
    Write-Host "Memória local: ativa"
    Write-Host "Fallback guiado: ativo"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host "Backup: $BackupRoot"
}
catch {
    Restore-ChatFiles
    throw
}
